PREFIX energia: <https://w3id.org/rastro/energia#>
SELECT ?name WHERE {
  {
    SELECT ?c (SUM(?g) AS ?total) WHERE {
      ?p a energia:ShaleProduction ;
         energia:declaredBy ?c ;
         energia:gas ?g .
    }
    GROUP BY ?c
    ORDER BY DESC(?total)
    LIMIT 5
  }
  ?c energia:name ?name .
}
ORDER BY DESC(?total)
